// Generated by esquadro: do not edit. The values a record's field took
// (@store(history)), on its page: a line over the last 90 days, with the
// lowest and the highest.
import { useQuery } from "@tanstack/react-query"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"
import { api } from "../api.ts"
import { display, SeriesChart } from "./dashboard.tsx"
import { describe } from "./errors.ts"
import { capitalize, t } from "./i18n.ts"
import type { FieldMeta, ResourceMeta } from "./meta.ts"
import { isMoney } from "./money.tsx"

/** A value a field took, and when, as the API answers it. */
export type Point = { value: unknown; at: string }

/** A value as a number, to compare: money by its amount. */
function amountOf(v: unknown): number {
  return Number(isMoney(v) ? v.amount : v)
}

/** The lowest and the highest of the values, as they came; none without values. */
export function lowHigh(points: readonly Point[]): { low: unknown; high: unknown } | undefined {
  if (points.length === 0) return undefined
  let low = points[0].value
  let high = low
  for (const p of points) {
    if (amountOf(p.value) < amountOf(low)) low = p.value
    if (amountOf(p.value) > amountOf(high)) high = p.value
  }
  return { low, high }
}

/** A card of the values a record's field took in the last 90 days. */
export function ValueHistory({ meta, field, op, id }: { meta: ResourceMeta; field: FieldMeta; op: string; id: string }) {
  const points = useQuery({
    queryKey: [meta.name, "values", field.name, id],
    queryFn: ({ signal }) =>
      (meta.api(api as never) as unknown as Record<string, (id: string, q: object, o: object) => Promise<{ items: Point[] }>>)[op](id, {}, { signal }),
    select: (page) => page.items,
  })
  const range = points.data && lowHigh(points.data)
  return (
    <Card className="min-w-0">
      <CardHeader>
        <CardTitle>
          {capitalize(field.label)} · {t("history")}
        </CardTitle>
      </CardHeader>
      <CardContent>
        {points.isPending && <Skeleton className="h-48 w-full" />}
        {points.isError && <p className="text-sm text-destructive">{describe(points.error)}</p>}
        {points.data && !range && <p className="py-6 text-center text-sm text-muted-foreground">{t("noValues")}</p>}
        {points.data && range && (
          <div className="flex flex-col gap-4">
            <dl className="flex gap-8 text-sm">
              <div>
                <dt className="text-muted-foreground">{t("low")}</dt>
                <dd className="font-semibold text-foreground tabular-nums">{display(field, range.low)}</dd>
              </div>
              <div>
                <dt className="text-muted-foreground">{t("high")}</dt>
                <dd className="font-semibold text-foreground tabular-nums">{display(field, range.high)}</dd>
              </div>
            </dl>
            <SeriesChart
              widget={ {
                name: `${field.name}-history`,
                label: field.label,
                kind: "line",
                x: "at",
                y: ["value"],
                columns: [{ name: "at", label: "", kind: "datetime", required: true }, { ...field, name: "value" }],
                fetch: async () => points.data,
              } }
              rows={points.data}
            />
          </div>
        )}
      </CardContent>
    </Card>
  )
}
